// ── Secret Service (libsecret) ─────────────────────────────────

declare module 'gi://Secret?version=1' {
    namespace Secret {
        class Schema {
            constructor(
                name: string,
                flags: SchemaFlags,
                attributes: Record<string, SchemaAttributeType>,
            );
        }
        const enum SchemaFlags {
            NONE = 0,
        }
        const enum SchemaAttributeType {
            STRING = 0,
        }
        function password_lookup_sync(
            schema: Schema,
            attributes: Record<string, string>,
            cancellable: unknown,
        ): string | null;
        function password_store_sync(
            schema: Schema,
            attributes: Record<string, string>,
            collection: string,
            label: string,
            password: string,
            cancellable: unknown,
        ): boolean;
        function password_clear_sync(
            schema: Schema,
            attributes: Record<string, string>,
            cancellable: unknown,
        ): boolean;
    }
    // eslint-disable-next-line import/no-default-export
    export default Secret;
}

